{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "awesome-ascend-skills",
  "version": "1.0.0",
  "description": "A comprehensive knowledge base for Huawei Ascend NPU development, structured as distributed AI Agent Skills. Includes npu-smi device management, HCCL performance testing, and ATC model conversion.",
  "owner": {
    "name": "Ascend AI Coding",
    "email": "ascend-ai-coding@example.com"
  },
  "plugins": [
    {
      "name": "npu-smi",
      "description": "Huawei Ascend NPU npu-smi command reference. Use for device queries (health, temperature, power, memory, processes, ECC), configuration (thresholds, modes, fan), firmware upgrades (MCU, bootloader, VRD), virtualization (vNPU), and certificate management.",
      "source": "./npu-smi",
      "category": "operations"
    },
    {
      "name": "hccl-test",
      "description": "HCCL (Huawei Collective Communication Library) performance testing for Ascend NPU clusters. Use for testing distributed communication bandwidth, verifying HCCL functionality, and benchmarking collective operations like AllReduce, AllGather, AlltoAll.",
      "source": "./hccl-test",
      "category": "testing"
    },
    {
      "name": "atc-model-converter",
      "description": "Complete toolkit for Huawei Ascend NPU model conversion and inference. Convert ONNX models to .om format using ATC tool, run Python inference on OM models using ais_bench, compare precision between CPU ONNX and NPU OM outputs, and end-to-end YOLO inference with Ultralytics.",
      "source": "./atc-model-converter",
      "category": "development"
    },
    {
      "name": "ascend-docker",
      "description": "Create Docker containers for Huawei Ascend NPU development with proper device mappings (davinci_manager, devmm_svm, hisi_hdc) and volume mounts (driver, sbin, home). Use when setting up Ascend development environments in Docker, running CANN applications in containers, or creating isolated NPU development workspaces.",
      "source": "./ascend-docker",
      "category": "operations"
    },
    {
      "name": "msmodelslim",
      "description": "Huawei Ascend NPU model compression tool for LLM, MoE, and multimodal models. Supports W4A8, W8A8, W8A8S, W8A16, W8A8C8 quantization and sparse quantization. Compatible with 20+ model families (Qwen, DeepSeek, LLaMA, GLM, Kimi, Baichuan, Yi, InternLM, Mistral, etc.). Includes precision auto-tuning, custom model integration guide, and vLLM-Ascend/MindIE deployment.",
      "source": "./msmodelslim",
      "category": "development"
    },
    {
      "name": "ais-bench",
      "description": "AI model evaluation tool for Ascend NPU. Supports accuracy evaluation (text, multimodal datasets), performance evaluation (latency, throughput, stress testing), vLLM/Triton inference, 15+ benchmarks (MMLU, GSM8K, MMMU, BFCL), multi-turn dialogue, Function Call, and custom datasets.",
      "source": "./ais-bench",
      "category": "testing"
    },
    {
      "name": "ascendc",
      "description": "AscendC development helper, provides AscendC development environment, compiler, and debugger. Supports C/C++ and Python programming on Ascend NPU. Includes sample code, tutorials, and best practices for AscendC development.",
      "source": "./ascendc",
      "category": "development"
    },
    {
      "name": "vllm-ascend",
      "description": "vLLM inference engine for Huawei Ascend NPU. Deploy LLMs with OpenAI-compatible API, offline batch inference, quantized model serving (W4A8, W8A8), tensor/pipeline parallelism for distributed inference, and performance optimization. Supports Qwen, DeepSeek, GLM, LLaMA models with Ascend-optimized kernels.",
      "source": "./vllm-ascend",
      "category": "development"
    }
  ]
}
